import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.D3sJ1xc1.js";const m=JSON.parse('{"title":"📜 Regulament Jafuri (Română)","description":"","frontmatter":{},"headers":[],"relativePath":"regulament-jafuri.md","filePath":"regulament-jafuri.md"}'),t={name:"regulament-jafuri.md"};function n(u,i,o,c,s,p){return e(),r("div",null,[...i[0]||(i[0]=[l('<h1 id="📜-regulament-jafuri-romana" tabindex="-1">📜 Regulament Jafuri (Română) <a class="header-anchor" href="#📜-regulament-jafuri-romana" aria-label="Permalink to &quot;📜 Regulament Jafuri (Română)&quot;">​</a></h1><hr><h2 id="cap-1-informatii-generale" tabindex="-1">CAP. 1 - INFORMAȚII GENERALE <a class="header-anchor" href="#cap-1-informatii-generale" aria-label="Permalink to &quot;CAP. 1 - INFORMAȚII GENERALE&quot;">​</a></h2><h3 id="_1-1-reguli-generale" tabindex="-1">1.1 Reguli generale <a class="header-anchor" href="#_1-1-reguli-generale" aria-label="Permalink to &quot;1.1 Reguli generale&quot;">​</a></h3><p>În cazul jafurilor care permit utilizarea ostaticilor, primul polițist ajuns la fața locului este considerat negociator.</p><h3 id="reguli" tabindex="-1">Reguli <a class="header-anchor" href="#reguli" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Jefuitorii nu au voie să captureze negociatorul.</li><li>Jefuitorii nu au voie să deschidă focul asupra negociatorului fără un motiv întemeiat de tip Roleplay.</li><li>Jefuitorii sunt obligați să comunice Poliției numărul total de infractori implicați în jaf.</li><li>Jefuitorii sunt obligați să comunice numărul total de ostatici.</li><li>Polițiștilor le este strict interzis să pătrundă în interiorul locației jefuite pe durata desfășurării jafului.</li><li>Jefuitorii nu pot părăsi locația până la încheierea negocierilor sau până la începerea confruntării.</li><li>Dacă o Bancă Mică, Banca Pacific, Banca Blaine sau Bijuteria sunt deja ocupate și alarma este activă, intervenția unei alte grupări este strict interzisă.</li><li>Jefuitorii au obligația de a comunica existența oamenilor de teren.</li><li>Poliția trebuie să urmărească, pe cât posibil, capturarea infractorilor în viață.</li><li>După negocierea unei căi libere, toți jefuitorii trebuie să părăsească imediat locația.</li><li>Este interzisă luarea ca ostatici a persoanelor care desfășoară joburi legale (mecanic, taximetrist, curier, poștaș etc.).</li><li>Este interzis ca jefuitorii să solicite Poliției să lase armele jos, să se pună în genunchi sau să execute alte acțiuni similare care elimină posibilitatea unui Roleplay echilibrat.</li><li>Poliția poate interveni doar dacă sunt executate focuri de armă înainte de declanșarea alarmei.</li><li>Jefuitorii nu pot deschide focul asupra Poliției înainte de declanșarea alarmei, cu excepția cazului în care Poliția a tras prima.</li></ul><hr><h2 id="cap-2-jafuri" tabindex="-1">CAP. 2 - JAFURI <a class="header-anchor" href="#cap-2-jafuri" aria-label="Permalink to &quot;CAP. 2 - JAFURI&quot;">​</a></h2><h3 id="_2-1-jaful-la-magazine" tabindex="-1">2.1 Jaful la Magazine <a class="header-anchor" href="#_2-1-jaful-la-magazine" aria-label="Permalink to &quot;2.1 Jaful la Magazine&quot;">​</a></h3><h4 id="participanti" tabindex="-1">Participanți <a class="header-anchor" href="#participanti" aria-label="Permalink to &quot;Participanți&quot;">​</a></h4><ul><li>Număr minim de infractori: <strong>2</strong></li><li>Număr maxim de infractori: <strong>3</strong></li></ul><h4 id="reguli-1" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-1" aria-label="Permalink to &quot;Reguli&quot;">​</a></h4><ul><li>Ostaticii nu sunt permiși.</li><li>Jefuitorii pot utiliza orice armă pe care o dețin.</li><li>Pot interveni doar polițiști cu gradul de <strong>Cadet</strong> sau <strong>Agent</strong>.</li><li>Este interzisă prezența oamenilor de teren în afara magazinului.</li><li>După spargerea seifului, jefuitorii pot părăsi imediat magazinul și nu sunt obligați să aștepte sosirea Poliției.</li></ul><hr><h3 id="_2-2-jaful-la-bancile-mici" tabindex="-1">2.2 Jaful la Băncile Mici <a class="header-anchor" href="#_2-2-jaful-la-bancile-mici" aria-label="Permalink to &quot;2.2 Jaful la Băncile Mici&quot;">​</a></h3><p><em>(Highway, Vinewood, Alta, Desert)</em></p><h4 id="participanti-1" tabindex="-1">Participanți <a class="header-anchor" href="#participanti-1" aria-label="Permalink to &quot;Participanți&quot;">​</a></h4><ul><li>Număr minim de infractori: <strong>5</strong></li><li>Număr maxim de participanți: <strong>8</strong></li><li>Ostaticii sunt interziși.</li></ul><h4 id="exemplu" tabindex="-1">Exemplu <a class="header-anchor" href="#exemplu" aria-label="Permalink to &quot;Exemplu&quot;">​</a></h4><ul><li>5 persoane în bancă.</li><li>3 oameni de teren.</li><li>Total: <strong>8 participanți</strong>.</li></ul><h4 id="reguli-2" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-2" aria-label="Permalink to &quot;Reguli&quot;">​</a></h4><ul><li>Organizarea infractorilor între interior și exterior este la alegerea grupării.</li><li>Jefuitorii pot elimina persoane care manifestă comportament suspect sau amenințător.</li><li>Persoanele neînarmate trebuie avertizate și somate să părăsească zona înainte de utilizarea forței.</li><li>Nici Poliția și nici jefuitorii nu sunt obligați să negocieze.</li><li>Dacă un polițist se apropie fără acordul jefuitorilor, aceștia pot deschide focul.</li><li>Aceeași regulă se aplică și Poliției.</li></ul><hr><h3 id="_2-3-jaful-la-bijuterie" tabindex="-1">2.3 Jaful la Bijuterie <a class="header-anchor" href="#_2-3-jaful-la-bijuterie" aria-label="Permalink to &quot;2.3 Jaful la Bijuterie&quot;">​</a></h3><h4 id="ostatici" tabindex="-1">Ostatici <a class="header-anchor" href="#ostatici" aria-label="Permalink to &quot;Ostatici&quot;">​</a></h4><ul><li>Sunt permiși între <strong>1 și 3 ostatici</strong>.</li><li>Ostaticii pot fi folosiți pentru negocierea unei căi libere.</li><li>Pentru fiecare ostatic se pot negocia între <strong>7 și 10 secunde</strong> de cale liberă.</li></ul><h4 id="definitia-caii-libere" tabindex="-1">Definiția căii libere <a class="header-anchor" href="#definitia-caii-libere" aria-label="Permalink to &quot;Definiția căii libere&quot;">​</a></h4><p>Prin <strong>cale liberă</strong> se înțelege perioada negociată în care jefuitorii pot părăsi locația fără ca Poliția să:</p><ul><li>deschidă focul;</li><li>blocheze intenționat ieșirile;</li><li>creeze situații de tip Powergaming prin eliminarea șanselor egale de evadare.</li></ul><h4 id="participanti-2" tabindex="-1">Participanți <a class="header-anchor" href="#participanti-2" aria-label="Permalink to &quot;Participanți&quot;">​</a></h4><ul><li>Număr minim de infractori: <strong>8</strong></li><li>Maximum <strong>3 oameni de teren</strong>.</li><li>Numărul minim de participanți îi include și pe oamenii de teren.</li></ul><hr><h3 id="_2-4-jaful-la-banca-blaine" tabindex="-1">2.4 Jaful la Banca Blaine <a class="header-anchor" href="#_2-4-jaful-la-banca-blaine" aria-label="Permalink to &quot;2.4 Jaful la Banca Blaine&quot;">​</a></h3><h4 id="participanti-3" tabindex="-1">Participanți <a class="header-anchor" href="#participanti-3" aria-label="Permalink to &quot;Participanți&quot;">​</a></h4><ul><li>Număr minim de infractori: <strong>8</strong></li><li>Nu există limită maximă.</li></ul><h4 id="reguli-3" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-3" aria-label="Permalink to &quot;Reguli&quot;">​</a></h4><ul><li>Organizarea participanților este la alegerea grupării.</li><li>Ostaticii sunt interziși.</li><li>Negocierile cu Poliția nu sunt permise.</li></ul><hr><h3 id="_2-5-jaful-la-banca-pacific" tabindex="-1">2.5 Jaful la Banca Pacific <a class="header-anchor" href="#_2-5-jaful-la-banca-pacific" aria-label="Permalink to &quot;2.5 Jaful la Banca Pacific&quot;">​</a></h3><h4 id="participanti-4" tabindex="-1">Participanți <a class="header-anchor" href="#participanti-4" aria-label="Permalink to &quot;Participanți&quot;">​</a></h4><ul><li>Număr minim de infractori: <strong>10</strong></li><li>Numărul oamenilor de teren este nelimitat.</li></ul><h4 id="reguli-4" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-4" aria-label="Permalink to &quot;Reguli&quot;">​</a></h4><ul><li>Ostaticii sunt interziși.</li><li>Gruparea își poate organiza membrii atât în interiorul băncii, cât și în exterior.</li><li>Jefuitorii pot elimina persoane care manifestă comportament suspect sau amenințător.</li><li>Persoanele neînarmate trebuie avertizate înainte de utilizarea forței.</li><li>Negocierile nu sunt obligatorii.</li><li>Sunt permise focurile de avertisment asupra Poliției atunci când aceasta încearcă să colecteze informații sau să surprindă pozițiile infractorilor.</li></ul><hr><h3 id="_2-6-jaful-la-atm-uri" tabindex="-1">2.6 Jaful la ATM-uri <a class="header-anchor" href="#_2-6-jaful-la-atm-uri" aria-label="Permalink to &quot;2.6 Jaful la ATM-uri&quot;">​</a></h3><h4 id="participanti-5" tabindex="-1">Participanți <a class="header-anchor" href="#participanti-5" aria-label="Permalink to &quot;Participanți&quot;">​</a></h4><ul><li>Număr minim de infractori: <strong>2</strong></li><li>Număr maxim de infractori: <strong>4</strong></li></ul><h4 id="reguli-5" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-5" aria-label="Permalink to &quot;Reguli&quot;">​</a></h4><ul><li>Jefuitorii pot elimina persoane care manifestă comportament suspect sau amenințător.</li><li>Persoanele neînarmate trebuie somate să părăsească zona înainte de utilizarea forței.</li></ul><hr><h2 id="cap-3-jefuirea-persoanelor" tabindex="-1">CAP. 3 - JEFUIREA PERSOANELOR <a class="header-anchor" href="#cap-3-jefuirea-persoanelor" aria-label="Permalink to &quot;CAP. 3 - JEFUIREA PERSOANELOR&quot;">​</a></h2><h3 id="_3-1-reguli-generale" tabindex="-1">3.1 Reguli generale <a class="header-anchor" href="#_3-1-reguli-generale" aria-label="Permalink to &quot;3.1 Reguli generale&quot;">​</a></h3><p>Jefuirea unui jucător trebuie să reprezinte o acțiune Roleplay realistă și de calitate.</p><h3 id="reguli-6" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-6" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>În timpul jafului trebuie să întrețineți un Roleplay coerent și realist.</li><li>Acțiunea trebuie să fie logică și să aibă un motiv Roleplay.</li><li>Nu recurgeți direct la folosirea armelor dacă situația poate fi rezolvată prin Roleplay.</li></ul><hr><h3 id="_3-2-bunuri-care-pot-fi-jefuite" tabindex="-1">3.2 Bunuri care pot fi jefuite <a class="header-anchor" href="#_3-2-bunuri-care-pot-fi-jefuite" aria-label="Permalink to &quot;3.2 Bunuri care pot fi jefuite&quot;">​</a></h3><p>În urma unei acțiuni Roleplay de jaf, puteți lua doar următoarele bunuri:</p><ul><li>Telefon.</li><li>Stație radio.</li><li>Apă.</li><li>Mâncare.</li><li>Toți banii cash deținuți de victimă.</li><li>Bunuri ilegale (arme, muniție, droguri și alte obiecte ilegale).</li></ul><hr><h3 id="_3-3-bunuri-care-nu-pot-fi-jefuite" tabindex="-1">3.3 Bunuri care NU pot fi jefuite <a class="header-anchor" href="#_3-3-bunuri-care-nu-pot-fi-jefuite" aria-label="Permalink to &quot;3.3 Bunuri care NU pot fi jefuite&quot;">​</a></h3><p>Este strict interzis să luați următoarele bunuri:</p><ul><li>Acte de identitate.</li><li>Permis de conducere.</li><li>Permis port-armă.</li><li>Alte documente personale.</li><li>Haine.</li><li>Accesorii.</li></ul><hr><h3 id="_3-4-zone-permise" tabindex="-1">3.4 Zone permise <a class="header-anchor" href="#_3-4-zone-permise" aria-label="Permalink to &quot;3.4 Zone permise&quot;">​</a></h3><p>Aceste interacțiuni sunt permise doar în zonele rău famate ale orașului.</p><h3 id="reguli-7" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-7" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Este interzis să jefuiți persoane în zone publice.</li><li>Este interzis să luați o persoană dintr-o zonă publică doar pentru a o transporta într-o zonă rău famată în scopul jefuirii.</li></ul><hr><h3 id="_3-5-reintoarcerea-victimei" tabindex="-1">3.5 Reîntoarcerea victimei <a class="header-anchor" href="#_3-5-reintoarcerea-victimei" aria-label="Permalink to &quot;3.5 Reîntoarcerea victimei&quot;">​</a></h3><p>Dacă persoana jefuită revine în aceeași zonă, aceasta poate fi jefuită din nou.</p><p>Este responsabilitatea victimei să își joace corect personajul și să respecte regula <strong>No Fear RP</strong>.</p><hr><h3 id="_3-6-recomandari" tabindex="-1">3.6 Recomandări <a class="header-anchor" href="#_3-6-recomandari" aria-label="Permalink to &quot;3.6 Recomandări&quot;">​</a></h3><p>Pentru o experiență cât mai plăcută:</p><ul><li>Încercați să creați acțiuni cât mai calitative.</li><li>Evitați utilizarea armelor încă din primele secunde ale interacțiunii.</li><li>Dacă un jucător încalcă regulamentul, deschideți un ticket și nu răspundeți la <strong>FAIL cu FAIL</strong>.</li></ul><hr><h2 id="cap-4-informatii-suplimentare" tabindex="-1">CAP. 4 - INFORMAȚII SUPLIMENTARE <a class="header-anchor" href="#cap-4-informatii-suplimentare" aria-label="Permalink to &quot;CAP. 4 - INFORMAȚII SUPLIMENTARE&quot;">​</a></h2><h3 id="_4-1-sanctiuni" tabindex="-1">4.1 Sancțiuni <a class="header-anchor" href="#_4-1-sanctiuni" aria-label="Permalink to &quot;4.1 Sancțiuni&quot;">​</a></h3><p>Încălcarea oricărei reguli din prezentul regulament poate fi sancționată cu <strong>Fail Roleplay</strong>, în funcție de gravitatea situației.</p><hr><h3 id="_4-2-safe-zone" tabindex="-1">4.2 Safe Zone <a class="header-anchor" href="#_4-2-safe-zone" aria-label="Permalink to &quot;4.2 Safe Zone&quot;">​</a></h3><p>Este strict interzisă pătrunderea într-o <strong>Safe Zone</strong> sau staționarea la limita acesteia în timpul obținut prin negocierea căii libere.</p><hr><h3 id="_4-3-interpretarea-regulamentului" tabindex="-1">4.3 Interpretarea regulamentului <a class="header-anchor" href="#_4-3-interpretarea-regulamentului" aria-label="Permalink to &quot;4.3 Interpretarea regulamentului&quot;">​</a></h3><p>Regulamentul nu poate fi interpretat în interes propriu pentru obținerea unor avantaje nejustificate.</p><p>Administrația serverului își rezervă dreptul de a interpreta regulamentul în spiritul Roleplay-ului și al echilibrului dintre jucători.</p><hr><h3 id="_4-4-modificarea-regulamentului" tabindex="-1">4.4 Modificarea regulamentului <a class="header-anchor" href="#_4-4-modificarea-regulamentului" aria-label="Permalink to &quot;4.4 Modificarea regulamentului&quot;">​</a></h3><p>Echipa administrativă își rezervă dreptul de a modifica prezentul regulament fără notificare prealabilă.</p><p>Recomandăm tuturor jucătorilor să recitească periodic regulamentul pentru a fi la curent cu eventualele modificări.</p><hr><h2 id="cap-5-obligativitate" tabindex="-1">CAP. 5 - OBLIGATIVITATE <a class="header-anchor" href="#cap-5-obligativitate" aria-label="Permalink to &quot;CAP. 5 - OBLIGATIVITATE&quot;">​</a></h2><h3 id="_5-1-filmarea-activitatilor-ilegale" tabindex="-1">5.1 Filmarea activităților ilegale <a class="header-anchor" href="#_5-1-filmarea-activitatilor-ilegale" aria-label="Permalink to &quot;5.1 Filmarea activităților ilegale&quot;">​</a></h3><p>Toți jucătorii sunt obligați să aibă înregistrarea video pornită pe întreaga durată a activităților ilegale desfășurate pe server.</p><h3 id="reguli-8" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-8" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Filmarea trebuie să surprindă întreaga acțiune.</li><li>În lipsa unei dovezi video, reclamațiile pot fi respinse.</li><li>Înregistrarea poate fi solicitată de membrii Staff în cazul unei reclamații sau verificări.</li></ul><hr><h2 id="📌-nota" tabindex="-1">📌 NOTĂ <a class="header-anchor" href="#📌-nota" aria-label="Permalink to &quot;📌 NOTĂ&quot;">​</a></h2><p>Respectarea prezentului regulament este obligatorie pentru toți jucătorii serverului <strong>LEGACY OF CLT</strong>.</p><p>Nerespectarea regulilor poate atrage sancțiuni administrative, inclusiv confiscarea bunurilor, suspendarea temporară sau permanentă a accesului pe server, în funcție de gravitatea faptei.</p>',102)])])}const h=a(t,[["render",n]]);export{m as __pageData,h as default};
